-- Miscellaneous real-world: Grafana, Superset, dbt-clickhouse, clickhouse-client generated
SELECT toStartOfInterval(toDateTime(ts), INTERVAL 60 second) AS t, avg(value) AS v FROM metrics WHERE ts >= toDateTime(1700000000) AND ts <= toDateTime(1700003600) GROUP BY t ORDER BY t ASC;
SELECT toUInt32(toStartOfInterval(ts, INTERVAL 1 MINUTE)) * 1000 AS time, count() AS value FROM web_events WHERE ts BETWEEN toDateTime(1700000000) AND toDateTime(1700003600) GROUP BY time ORDER BY time;
SELECT name FROM system.databases ORDER BY name;
SELECT database, name FROM system.tables WHERE engine NOT LIKE '%View' ORDER BY 1, 2;
SELECT * FROM events LIMIT 1 SETTINGS readonly = 1;
SELECT 'ok' FORMAT Null;
SELECT count() FROM events WHERE toDate(ts) = today() FORMAT TSV;
CREATE TABLE dbt_tmp__dbt_tmp (id UInt64, v String) ENGINE = MergeTree ORDER BY id SETTINGS replicated_deduplication_window = 0;
CREATE TABLE IF NOT EXISTS t_final (id UInt64, v String, ts DateTime) ENGINE = ReplacingMergeTree(ts) PRIMARY KEY id ORDER BY id;
CREATE TABLE t_primary (a UInt32, b UInt32) ENGINE = MergeTree PRIMARY KEY a ORDER BY (a, b);
CREATE TABLE t_comment (a UInt8) ENGINE = MergeTree ORDER BY a COMMENT 'a table';
CREATE TABLE t_ttl_group (d Date, k UInt32, x UInt32, y UInt32) ENGINE = MergeTree ORDER BY (k, toStartOfMonth(d)) TTL d + INTERVAL 1 MONTH GROUP BY k, toStartOfMonth(d) SET x = max(x), y = min(y);
CREATE TABLE t_col_ttl (d DateTime, a Int32 TTL d + INTERVAL 1 DAY, b Int32) ENGINE = MergeTree ORDER BY d;
CREATE TABLE t_codec (a UInt64 CODEC(Delta(8), LZ4), b Float64 CODEC(Gorilla, ZSTD(3)), c String CODEC(ZSTD)) ENGINE = MergeTree ORDER BY a;
CREATE TABLE t_ipv (a IPv4, b IPv6, c UUID, d Date32, e DateTime('UTC'), f FixedString(16), g Bool, h Int128, i Float32) ENGINE = MergeTree ORDER BY a;
CREATE TABLE t_complex (a Array(Array(UInt8)), b Map(String, Array(UInt32)), c Tuple(UInt8, String), d Nullable(DateTime64(6, 'UTC')), e Array(Nullable(String)), f LowCardinality(Nullable(String)), g Map(LowCardinality(String), UInt64)) ENGINE = MergeTree ORDER BY tuple();
CREATE TABLE t_agg (a SimpleAggregateFunction(sum, UInt64), b SimpleAggregateFunction(max, DateTime), c AggregateFunction(groupArray, String)) ENGINE = AggregatingMergeTree ORDER BY tuple();
CREATE TEMPORARY TABLE tmp1 (a UInt8) ENGINE = Memory;
CREATE TEMPORARY TABLE tmp2 ENGINE = Memory AS SELECT 1 AS a;
CREATE TABLE t_settings (a UInt8) ENGINE = MergeTree ORDER BY a SETTINGS storage_policy = 'tiered', min_bytes_for_wide_part = 0, merge_with_ttl_timeout = 3600;
CREATE TABLE t_part_expr (ts DateTime, a UInt8) ENGINE = MergeTree PARTITION BY (toYYYYMM(ts), a % 4) ORDER BY ts;
CREATE TABLE t_orderby_expr (ts DateTime, u UInt64) ENGINE = MergeTree ORDER BY (toStartOfHour(ts), cityHash64(u) % 16, u);
CREATE TABLE t_ver (id UInt64, sign Int8, ver UInt32) ENGINE = VersionedCollapsingMergeTree(sign, ver) ORDER BY id;
CREATE TABLE t_cons (a UInt8, CONSTRAINT c1 CHECK a > 0, CONSTRAINT c2 ASSUME a < 100) ENGINE = MergeTree ORDER BY a;
CREATE TABLE t_cmt (a UInt8 COMMENT 'col a', b String CODEC(ZSTD) COMMENT 'col b') ENGINE = MergeTree ORDER BY a;
CREATE TABLE t_ro (a UInt8) ENGINE = MergeTree ORDER BY a SETTINGS index_granularity = 8192, index_granularity_bytes = 10485760;
CREATE TABLE t_sk (a UInt8, b String, INDEX i1 (a, b) TYPE set(100) GRANULARITY 2, INDEX i2 lower(b) TYPE ngrambf_v1(4, 1024, 1, 0) GRANULARITY 1) ENGINE = MergeTree ORDER BY a;
CREATE TABLE t_proj (a UInt8, b UInt8, PROJECTION p1 (SELECT a, sum(b) GROUP BY a)) ENGINE = MergeTree ORDER BY a;
